// Integration: the plugin's real `apply` against a real Cordis context and the
// real services — the `llm` service (`LlmRuntime`) that validates every
// registration the plugin makes (the adapter route and its metadata, the
// configurable-provider directory entry, model discovery) and the `tools`
// service (`ToolRuntime`) plus the real local attachment store
// (`LocalAttachmentStore`) that the `generate_image` tool registers into and
// writes generated bytes through.
import assert from 'node:assert/strict';
import { existsSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import test, { after } from 'node:test';
import { fileURLToPath } from 'node:url';
import { Context } from '@deepseek-ai/cordis';
import LocalAttachmentStore from '@deepseek-ai/dsh-attachment-local';
import LlmRuntime from '@deepseek-ai/dsh-llm';
import FileSettingsProvider from '@deepseek-ai/dsh-settings-file';
import SystemPrompt from '@deepseek-ai/dsh-system-prompt';
import ToolRuntime from '@deepseek-ai/dsh-tools';
import {
	Config,
	NS,
	ROUTE,
	apply,
	inject,
	name as pluginName,
} from '../lib/index.js';

/**
 * The isolated attachment store root for this run. It must stay outside the
 * real `~/.dsh`, so a test never writes user data.
 */
const ATTACHMENTS_HOME = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '_artifact-check', 'tmp-attachments');

/** The isolated settings home for this run, also outside the real `~/.dsh`. */
const SETTINGS_HOME = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '_artifact-check', 'tmp-settings-integration');
rmSync(ATTACHMENTS_HOME, { recursive: true, force: true });
rmSync(SETTINGS_HOME, { recursive: true, force: true });

/** Monotonic per-mount document index: one settings file per mounted host. */
let mountSeq = 0;

/** A 2x2 PNG, produced by the same codec the attachment store normalizes with. */
const PNG_BASE64 = 'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAACXBIWXMAAAPoAAAD6AG1e1JrAAAAEklEQVQImWM4ISd3Qk6OAUIBAB8mBBGFRCvEAAAAAElFTkSuQmCC';

/** One Gemini image response body carrying that PNG. */
function imageResponse() {
	return new Response(JSON.stringify({
		candidates: [{
			content: { role: 'model', parts: [{ inlineData: { mimeType: 'image/png', data: PNG_BASE64 } }] },
			finishReason: 'STOP',
		}],
	}), { status: 200, headers: { 'content-type': 'application/json' } });
}

/**
 * Mount the plugin on a fresh context whose `llm` service is the real runtime,
 * capturing the plugin context and the config reference the schema resolved to.
 * The real system-prompt, tool, and attachment services are mounted too, so the
 * `generate_image` registration and its execution path are the production ones;
 * the attachment store is pointed at an isolated directory.
 * @param {object} [config] - the mounting entry's raw config block.
 * @returns {Promise<{ ctx: object, pluginCtx: object, configRef: object }>} the harness.
 */
async function mount(config = {}) {
	const ctx = new Context();
	await ctx.plugin(SystemPrompt);
	await ctx.plugin(ToolRuntime);
	await ctx.plugin(LocalAttachmentStore, { dshHome: ATTACHMENTS_HOME });
	await ctx.plugin(LlmRuntime);
	await ctx.plugin(FileSettingsProvider, {
		path: join(SETTINGS_HOME, `mount-${mountSeq += 1}.yaml`),
		watch: false,
	});

	let pluginCtx;
	let configRef;
	await ctx.plugin({
		name: pluginName,
		inject,
		Config,
		apply(childCtx, childConfig) {
			pluginCtx = childCtx;
			configRef = childConfig;
			return apply(childCtx, childConfig);
		},
	}, config);

	assert.ok(pluginCtx, 'the plugin activated');
	return { ctx, pluginCtx, configRef };
}

/** Let the settings service's queued watcher tails run: they notify on a microtask. */
const settleSettings = () => new Promise((resolve) => { setTimeout(resolve, 0); });

test('apply() registers one live adapter with the real runtime', async () => {
	const { ctx, configRef } = await mount({ region: 'us-central1', projectId: 'vertex-proj' });

	assert.equal(configRef.region, 'us-central1', 'the mounting entry reaches the plugin resolved');
	assert.equal(configRef.tier, 'standard', 'defaults are resolved for the plugin');
	assert.equal(ctx.settings.get(NS).region, 'us-central1', 'the entry is the section base layer');

	assert.deepEqual(ctx.llm.listProviders(), [{ id: ROUTE, name: 'Google Vertex AI' }]);

	const models = await ctx.llm.listModels(ROUTE);
	assert.ok(models.length >= 10);
	assert.ok(models.every((model) => model.provider === ROUTE && typeof model.id === 'string' && model.name.length > 0));

	const resolved = await ctx.llm.resolveModelInfo(ROUTE, 'gemini-2.5-pro');
	assert.equal(resolved.provider, ROUTE);
	assert.equal(resolved.name, 'Gemini 2.5 Pro');
	assert.deepEqual(resolved.inputModalities, ['text', 'image']);
	assert.equal(resolved.context.contextWindow, 1048576);
	assert.equal(resolved.defaultMaxTokens, 65536);
	assert.deepEqual(resolved.reasoning.efforts.map((effort) => effort.id), ['minimal', 'low', 'medium', 'high']);

	const unlisted = await ctx.llm.resolveModelInfo(ROUTE, 'gemini-future-model');
	assert.equal(unlisted.name, 'gemini-future-model');
	assert.equal(unlisted.reasoning, undefined, 'an unknown model advertises no reasoning control');

	const directory = ctx.llm.listConfigurableProviders();
	assert.deepEqual(directory, [{
		provider: ROUTE,
		displayName: 'Google Vertex AI',
		settingsNs: NS,
		settingsPath: [],
		declared: false,
	}]);
});

test('discovery serves the catalog through the runtime', async () => {
	const { ctx } = await mount({ region: 'global', customModels: ['my-tuned-model'] });

	const discovered = await ctx.llm.discoverModels(NS, { provider: ROUTE });
	assert.ok(discovered.length > 0);
	assert.ok(discovered.some((model) => model.id === 'gemini-2.5-pro'));
	assert.ok(discovered.some((model) => model.id === 'my-tuned-model'), 'configured custom models are advertised');
	assert.equal(new Set(discovered.map((model) => model.id)).size, discovered.length, 'ids are deduplicated');

	await assert.rejects(
		ctx.llm.discoverModels('a-namespace-nobody-registered', { provider: ROUTE }),
		(error) => error.code === 'NO_DISCOVERY',
	);
});

test('a live settings write reaches the adapter and the directory without a remount', async () => {
	const { ctx } = await mount({ displayName: 'Google Vertex AI', region: 'global' });

	// The settings document is the user layer over this entry's config block, and
	// its watcher is what re-derives the surfaces the plugin registered.
	await ctx.settings.update(NS, { displayName: 'Vertex After Edit', region: 'europe-west1' });
	await settleSettings();

	assert.equal(ctx.settings.get(NS).displayName, 'Vertex After Edit');
	assert.deepEqual(ctx.llm.listProviders(), [{ id: ROUTE, name: 'Vertex After Edit' }]);
	assert.equal(ctx.llm.listConfigurableProviders()[0].displayName, 'Vertex After Edit');

	const discovered = await ctx.llm.discoverModels(NS, { provider: ROUTE });
	assert.ok(discovered.length > 0, 'discovery keeps serving after an edit');
});

test('an invalid config never activates the plugin', async () => {
	const ctx = new Context();
	await ctx.plugin(LlmRuntime);
	let applied = 0;
	const fiber = ctx.plugin({
		name: pluginName,
		inject,
		Config,
		apply(...args) {
			applied += 1;
			return apply(...args);
		},
	}, { streamIdleTimeoutMs: 10 });
	// The runtime reports the rejected config on the fiber; the plugin must not
	// have registered anything from it.
	await (fiber.await?.() ?? Promise.resolve()).catch(() => {});
	await new Promise((resolve) => { setTimeout(resolve, 10); });
	assert.equal(applied, 0, 'a config that fails validation never activates the plugin');
	assert.deepEqual(ctx.llm.listProviders(), [], 'nothing was registered');
});

test('a full runtime call reaches Vertex and returns harness chunks', async () => {
	const encoder = new TextEncoder();
	const calls = [];
	globalThis.fetch = async (url, init) => {
		calls.push({ url, init });
		return new Response(new ReadableStream({
			start(controller) {
				for (const frame of [
					'data: {"candidates":[{"content":{"parts":[{"text":"Hi there"}]}}]}\n\n',
					'data: {"usageMetadata":{"promptTokenCount":10,"candidatesTokenCount":3,"totalTokenCount":13}}\n\n',
					'data: {"candidates":[{"finishReason":"STOP"}]}\n\n',
				]) controller.enqueue(encoder.encode(frame));
				controller.close();
			},
		}), { status: 200, headers: { 'content-type': 'text/event-stream' } });
	};
	process.env.GOOGLE_CLOUD_API_KEY = 'test-api-key';
	try {
		const { ctx } = await mount({ region: 'global' });
		const chunks = [];
		for await (const chunk of ctx.llm.stream({
			provider: ROUTE,
			model: 'gemini-3.8-flash',
			system: 'be brief',
			messages: [{ id: 'm1', role: 'user', content: [{ type: 'text', text: 'hello' }], source: { kind: 'user' } }],
		})) chunks.push(chunk);

		assert.deepEqual(chunks.map((chunk) => chunk.type), ['block-start', 'text-delta', 'block-end', 'usage', 'finish']);
		assert.equal(chunks[1].text, 'Hi there');
		assert.deepEqual(chunks[2].block, { type: 'text', text: 'Hi there' });
		assert.deepEqual(chunks[3].usage, { inputTokens: 10, outputTokens: 3, totalTokens: 13 });
		assert.deepEqual(chunks[4].reason, { kind: 'stop' });

		const [call] = calls;
		const url = new URL(call.url);
		assert.equal(`${url.origin}${url.pathname}`, 'https://aiplatform.googleapis.com/v1/publishers/google/models/gemini-3.8-flash:streamGenerateContent');
		assert.equal(url.searchParams.get('alt'), 'sse');
		assert.equal(url.searchParams.get('key'), 'test-api-key');
		assert.equal(call.init.headers['content-type'], 'application/json');
		assert.ok(call.init.headers['user-agent'].length > 0, 'attribution headers ride every request');
		assert.deepEqual(JSON.parse(call.init.body), {
			contents: [{ role: 'user', parts: [{ text: 'hello' }] }],
			systemInstruction: { parts: [{ text: 'be brief' }] },
			generationConfig: { maxOutputTokens: 65536 },
		});
	} finally {
		delete process.env.GOOGLE_CLOUD_API_KEY;
	}
});

test('a missing credential surfaces as a failure chunk, not a thrown request', async () => {
	globalThis.fetch = async () => {
		throw new Error('the adapter must not fetch without a credential');
	};
	const { ctx } = await mount({ apiKeyEnv: 'GOOGLE_CLOUD_API_KEY_ABSENT_FROM_THE_ENVIRONMENT' });
	const chunks = [];
	for await (const chunk of ctx.llm.stream({
		provider: ROUTE,
		model: 'gemini-3.8-flash',
		messages: [{ id: 'm1', role: 'user', content: [{ type: 'text', text: 'hello' }], source: { kind: 'user' } }],
	})) chunks.push(chunk);
	assert.deepEqual(chunks.map((chunk) => chunk.type), ['finish']);
	assert.equal(chunks[0].reason.kind, 'error');
	assert.equal(chunks[0].reason.failure.code, 'MISSING_CREDENTIAL');
	assert.match(chunks[0].reason.failure.message, /GOOGLE_CLOUD_API_KEY_ABSENT_FROM_THE_ENVIRONMENT/);
});

test('generate_image registers into the real tool registry once the attachment store is mounted', async () => {
	const { ctx } = await mount({ region: 'global' });

	const tool = ctx.tools.get('generate_image');
	assert.ok(tool, 'the image tool is registered');
	assert.deepEqual(Object.keys(tool.parameters.properties).sort(), ['aspect_ratio', 'count', 'model', 'prompt']);
	assert.deepEqual(tool.parameters.required, ['prompt']);
	assert.deepEqual(tool.parameters.properties.aspect_ratio.enum, ['1:1', '16:9', '9:16', '4:3', '3:4']);
	assert.equal(typeof tool.output.render, 'function');

	const published = ctx.tools.schemas().find((schema) => schema.name === 'generate_image');
	assert.ok(published, 'the model-facing schema is published');
	assert.match(published.description, /Vertex AI/);
	assert.ok(published.parameters.properties.model, 'the model argument is advertised');
});

test('a full runtime call commits a real attachment and returns text plus image blocks', async () => {
	const calls = [];
	globalThis.fetch = async (url, init) => {
		calls.push({ url, init });
		return imageResponse();
	};
	process.env.GOOGLE_CLOUD_API_KEY = 'test-api-key';
	try {
		const { ctx } = await mount({ region: 'global' });
		const result = await ctx.tools.execute({
			name: 'generate_image',
			callId: 'call-1',
			arguments: { prompt: 'a red circle on white', count: 2 },
			signal: new AbortController().signal,
		});

		assert.equal(result.isError, false);
		assert.deepEqual(result.content.map((block) => block.type), ['text', 'image', 'image']);
		assert.match(result.content[0].text, /gemini-2\.5-flash-image generated 2 images at 1:1\./);
		assert.equal(calls.length, 2, 'a Gemini batch is one request per image');

		const [image] = result.value.images;
		assert.equal(image.mediaType, 'image/png');
		assert.equal(image.width, 2);
		assert.equal(image.height, 2);
		assert.ok(image.bytes > 0);
		assert.ok(image.name.endsWith('.png'));
		assert.ok(result.content[0].text.includes(image.hostPath), 'the text envelope names the host path');
		assert.ok(existsSync(image.hostPath), 'the reported host path is a real file on disk');
		assert.equal(result.content[1].attachment.attachmentId, image.attachmentId);
		assert.equal(result.content[1].attachment.mediaType, 'image/png');
	} finally {
		globalThis.fetch = undefined;
		delete process.env.GOOGLE_CLOUD_API_KEY;
	}
});

test('the image settings are live: the tool follows a settings write', async () => {
	const calls = [];
	globalThis.fetch = async (url, init) => {
		calls.push({ url, init });
		return imageResponse();
	};
	process.env.GOOGLE_CLOUD_API_KEY = 'test-api-key';
	try {
		const { ctx } = await mount({ region: 'global' });
		assert.ok(ctx.tools.get('generate_image'), 'registered by default');

		await ctx.settings.update(NS, {
			imageModel: 'gemini-3.1-flash-lite-image',
			imageAspectRatio: '9:16',
			imageCount: 1,
		});
		await settleSettings();

		await ctx.tools.execute({
			name: 'generate_image',
			callId: 'call-2',
			arguments: { prompt: 'a tall blue square' },
			signal: new AbortController().signal,
		});
		const url = new URL(calls[0].url);
		assert.match(url.pathname, /gemini-3\.1-flash-lite-image:generateContent$/);
		assert.deepEqual(JSON.parse(calls[0].init.body).generationConfig.imageConfig, { aspectRatio: '9:16' });

		await ctx.settings.update(NS, { imageToolEnabled: false });
		await settleSettings();
		assert.equal(ctx.tools.get('generate_image'), undefined, 'turning the setting off unregisters the tool');

		await ctx.settings.update(NS, { imageToolEnabled: true });
		await settleSettings();
		assert.ok(ctx.tools.get('generate_image'), 'turning it back on registers the tool again');
	} finally {
		globalThis.fetch = undefined;
		delete process.env.GOOGLE_CLOUD_API_KEY;
	}
});

test('the tool refuses cleanly when the route has no credential', async () => {
	globalThis.fetch = async () => {
		throw new Error('the tool must not fetch without a credential');
	};
	try {
		const { ctx } = await mount({ apiKeyEnv: 'GOOGLE_CLOUD_API_KEY_ABSENT_FROM_THE_ENVIRONMENT' });
		const result = await ctx.tools.execute({
			name: 'generate_image',
			callId: 'call-3',
			arguments: { prompt: 'a circle' },
			signal: new AbortController().signal,
		});
		assert.equal(result.isError, true);
		assert.match(result.content[0].text, /GOOGLE_CLOUD_API_KEY_ABSENT_FROM_THE_ENVIRONMENT/);
	} finally {
		globalThis.fetch = undefined;
	}
});

// Leave no generated bytes behind: the store is content-addressed and this run
// owns every file under it.
after(() => {
	rmSync(ATTACHMENTS_HOME, { recursive: true, force: true });
});

console.log('plugin.integration.test.mjs: all assertions passed');
